switch (udev->speed) {
case USB_SPEED_LOW:
	speed = "1.5";
	break;
case USB_SPEED_UNKNOWN:
case USB_SPEED_FULL:
	speed = "12";
	break;
case USB_SPEED_HIGH:
	speed = "480";
	break;
default:
	speed = "unknown";
}

dev_info(&intf->dev,
	"New device %s %s @ %s Mbps (%04x:%04x, interface %d, class %d)\n",
	udev->manufacturer ? udev->manufacturer : "",
